import{_ as B,H as e,f as t,i}from"./chunks/framework.BH2BK_3i.js";const F=JSON.parse('{"title":"第九封信-阳光之下没什么新鲜事儿（上）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第九封信-阳光之下没什么新鲜事儿（上）.md","filePath":"去无方向的信/第九封信-阳光之下没什么新鲜事儿（上）.md","lastUpdated":1795542896000}'),s={name:"去无方向的信/第九封信-阳光之下没什么新鲜事儿（上）.md"};function n(a,E,p,A,o,r){return e(),t("div",null,[...E[0]||(E[0]=[i('<h1 id="第九封信-阳光之下没什么新鲜事儿-上" tabindex="-1">第九封信-阳光之下没什么新鲜事儿（上） <a class="header-anchor" href="#第九封信-阳光之下没什么新鲜事儿-上" aria-label="Permalink to &quot;第九封信-阳光之下没什么新鲜事儿（上）&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/3.png" alt=""></a></p><ul><li>写在前面</li></ul><p>在这广渺浩瀚的宇宙中，每一层时间切片上都罗布着无穷尽的事情，曾经有人试图在这万千纷繁中多少缕清哪怕一点点头绪，还曾经有人妄图寻得 &quot; THE ANSWER to Life, the Universeand Everything &quot;……于是，我们知道了“42”这个宇宙终极答案，世界上唯一一个没有问题与之相匹配的答案。</p><p>我不确定有关 Life、Universe 和 Everything 的答案到底是不是“42”，但我知道另一条“宇宙真理”，无论日升日落，无论月圆月缺，无论风起风息，无论云卷云舒，无论雪飘雨摇，无论烟笼雾散，只要太阳不灭，他就亘古常在……他就是“16”。</p><p>生生：</p><p>你好哇。</p><p>前几天我用一张照片儿举例，分析了为什么那张照片儿的参数一定要是 [1/125s F8 ISO200]，而不能是 [1/30s F16 ISO200]，或 [1/1000s F2.8 ISO200]，或 [1/2000s F16 ISO12800]。</p><p>我当时说，如果现在给你一组参数，你应该也可以自己分析出为什么是这样而不是那样了，但最后我问：如果从一开始就要你自己拿主意，要你自己定出一个快门值，一个光圈值，一个ISO 值，你该从哪儿下手呢？今天要说的就是这个事儿。</p><p>我接触过很多用 M 档的人，他们坚持要自己旋拧光圈、自己调节快门、自己设置 ISO，因为这样显得他们特专业，但他们确定一张照片儿曝光是否合理的标准是看相机上的那个屏幕：看著有点亮就随便缩缩光圈、催催快门或降降 ISO；看著有点暗就随便放放光圈、收收快门或提提 ISO。</p><p>还有一些人，他们用 M 档，但是他们信不过屏幕，因为屏幕亮度是可以调的，看着亮不一定真的亮，看着暗不一定真的暗。所以，他们会看相机上的曝光指示标尺，或者看一个叫“直方图”的东西，这是两个我们可能永远也不会讲到的没用的东西。</p><p>我粗浅地认为，M 档，在绝大多数情况下，显然是不能这么来用的，因为这样搞，就跟 P 档没有区别了，甚至，比 P 档用着还慢，何必呢？不如就直接用 P 档，但如果用 P 档，又不如直接用手机拍，这我之前也说过。</p><ul><li><p>所以，现在，请允许我先来赋诗一首：</p></li><li><p>阳光十六阴天八</p></li><li><p>多云十一日暮四</p></li><li><p>乌云压顶五点六</p></li><li><p>雪天落雨同日暮</p></li><li><p>这就是“阳光十六法则” (The Sunny 16 Rule)。</p></li></ul><p>里面的数字代表的都是光圈值，意思就是阳光灿烂的时候用 F16，阴天的时候用 F8，多云的时候用 F11，太阳刚落山且天还没完全黑的时候用 F4，下雨下雪的时候也用 F4。</p><p>相应的，在光圈值定下来以后，快门和 ISO 只要互为倒数就行了，比如：在阳光灿烂的一天，我们把光圈设为 F16，快门和 ISO 可以是 1/100s 和 ISO100，或 1/200s 和 ISO200，或1/400s 和 ISO400，或更多的倒数组合。</p><p>你一向很细心，所以我猜你已经发现问题了，那就是，1/100s、1/200s 和 1/400s 什么的，并不是我们前面说过的大档，我说过要坚决拥护大档，所以，我们要用 1/125s、1/250s 和1/500s。</p><p>于是，我们就得到了一组基础参数：1/125s F16 ISO100，这意味着，只要环境是阳光灿烂，我用这组参数，就能拍出曝光准确的照片儿。</p><p>同理，如果多云，那标准的曝光参数就是 1/125s F11 ISO100；如果阴天，那标准的曝光参数就是 1/125s F8 ISO100；如果（一般的）乌云来了，那标准的曝光参数就是 1/125sF5.6 ISO100；如果因为下雨下雪天很沉，那标准的曝光参数就是 1/125s F4 ISO100，日暮时分跟下雨下雪一样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%258A%25EF%25BC%2589/4.png" alt=""></a></p><p>我管这种标准的基础曝光参数叫锚点参数。</p><p>这不是什么学术的叫法，只是我这么叫，方便后面写东西，所以不用特别当回事儿。</p><p>这基本就是阳光十六法则的全部内容了，但这也只是这个法则的冰山一角……我们到底要怎么用这个玩意儿？咱们之后有时间再细聊。</p>',24)])])}const g=B(s,[["render",n]]);export{F as __pageData,g as default};
